    仅适配素净
   ============================================ */
@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@100..900&display=swap');

/* ----------🤍custom🤍---------- */
:root {
  /* id */
  --custom-id-text: "@id";

  /* 个签 */
  --custom-title-caption: " 我知这世界本如露水般短暂，然而，然而。 ";

  /* 占位符 */
  --custom-placeholder-text: "Send something…";

  /* 图片 reaction tag*/
  --img-tag-1: "🤍 520";
  --img-tag-2: "🪽 134";

/* user 引用条长度 */
  --reply-text-me-max: 200px; /* 引用条太长缩小 反之增大 */
}

/* ----------🤍end🤍---------- */

/* ----------variables---------- */
:root {
  --plain-avatar-size: 35px;
  --plain-avatar-radius: 50%;
  --plain-avatar-gap: 8px;
  --plain-content-max-width: 78%;
  --plain-gap-between-groups: 36px;
  --plain-gap-within-group: 16px;
  --plain-padding-right-them: 40px;
  --plain-padding-left-me: 40px;
  --detached-max-width: min(54vw, 260px);
  --reply-name-max: 160px;
  --reply-text-them-max: 220px;   
  --quote-side-offset: 7vw;
  --quote-rail-width: 80vw;
  --thinking-btn-bg: transparent;
  --thinking-btn-border: none;
  --thinking-btn-shadow: none;
  --thinking-btn-color: #9a9aa5;
  --reply-bar-accent: rgb(227, 220, 224);
  --chat-header-avatar-size: 48px;
  --plus-btn-icon: url('https://atnefallhmhz.vercel.app/f/menuicon-0889qs.png');

}
/* ----------1. bubbles---------- */
.msg-plain {
  position: relative;
  z-index: 0;
  overflow: visible;
  border-radius: 0 !important;
  padding: 7px 12px 7px !important;
  color: #3f3f3f !important;
}
.msg-plain-me {
  background: rgba(240, 234, 237, 0.7) !important;
  border: 1px solid #e1e6eb !important;
  color: #3f3f3f !important;
}
.msg-plain-them {
  background: rgba(234, 235, 241, 0.7) !important;
  border: 1px solid #ebe7eb !important;
  color: #3f3f3f !important;
}
.msg-plain-me.plain-last,
.msg-plain-me.plain-single,
.msg-plain-them.plain-first,
.msg-plain-them.plain-single {
  border-bottom: 0 !important;
}
[data-theme-style="plain"] .msg-bubble-wrapper.msg-them.is-first {
  margin-bottom: calc(var(--plain-gap-within-group) + 2px) !important;
}
.msg-bubble-wrapper,
.msg-content-stack {
  overflow: visible;
}
.msg-plain-me.plain-last::before,
.msg-plain-me.plain-single::before,
.msg-plain-them.plain-first::before,
.msg-plain-them.plain-single::before {
  content: "";
  position: absolute;
  left: -1px;
  right: -1px;
  top: calc(100% - 1px);
  height: 12px;
  background-repeat: repeat-x;
  background-size: auto 71px;
  background-position: left -24px;
  pointer-events: none;
  z-index: 1;
}
.msg-plain-me.plain-last::before,
.msg-plain-me.plain-single::before {
  background-image: url("https://atnefallhmhz.vercel.app/f/bluelace-dyhi6c.png");
}
.msg-plain-them.plain-first::before,
.msg-plain-them.plain-single::before {
  background-image: url("https://atnefallhmhz.vercel.app/f/pinklace-t2hrld.png");
}
.msg-plain-me.plain-last::after,
.msg-plain-me.plain-single::after {
  content: "";
  position: absolute;
  right: calc(100% + 5px);
  top: 50%;
  width: 25px;
  height: 25px;
  background: url("https://atnefallhmhz.vercel.app/f/bluewing-ra1cz8.png") no-repeat center / contain;
  pointer-events: none;
  transform: translateY(-50%);
  transform-origin: right center;
  animation: wing-sway 2s ease-in-out infinite;
}
.msg-plain-them.plain-first::after,
.msg-plain-them.plain-single::after {
  content: "";
  position: absolute;
  left: calc(100% + 5px);
  top: 50%;
  width: 25px;
  height: 25px;
  background: url("https://atnefallhmhz.vercel.app/f/pinkwing-t1kiwd.png") no-repeat center / contain;
  pointer-events: none;
  transform: translateY(-50%);
  transform-origin: left center;
  animation: wing-sway 2s ease-in-out infinite;
}
@keyframes wing-sway {
  0%, 100% { transform: translateY(-50%) rotate(6deg); }
  50%      { transform: translateY(-50%) rotate(-6deg); }
}
/* ----------2. avatars---------- */

[data-theme-style="plain"] .msg-avatar-them-container {
  visibility: hidden;
  pointer-events: none;
  position: relative;
}
