/* ----------13. sim card---------- */
.msg-radius-media:has(.msg-sim-card),
.bubble-deco:has(.msg-sim-card),
.msg-bubble-container:has(.msg-sim-card),
.msg-content-stack:has(.msg-sim-card){
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  overflow: visible !important;
  background: transparent !important;
}
.msg-sim-card{
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  width: 180px !important;
  padding: 0 !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 0 !important;
  overflow: visible !important;
  cursor: pointer;
  filter: drop-shadow(0 8px 18px rgba(0,0,0,.1));
  font-family: "Noto Sans SC", sans-serif;
  transform: translateY(-24px);
  margin-bottom: -46px !important;
}
.msg-sim-card::before,
.msg-sim-card::after{ display: none !important; }
.msg-sim-card .msg-sim-texture,
.msg-sim-card .msg-sim-loc-tag,
.msg-sim-card .msg-sim-date{ box-shadow: none !important; }
.msg-sim-card > .msg-sim-texture,
.msg-sim-card > .msg-sim-loc-tag,
.msg-sim-card > .msg-sim-date{
  box-sizing: border-box;
  width: 100% !important;
  min-height: 0 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  gap: 8px;
  padding: 9px 12px !important;
  margin: 0 !important;
  background: #ffffff !important;
  border: none !important;
  border-bottom: 1px solid #ededed !important;
  border-radius: 0 !important;
  position: static !important;
  inset: auto !important;
  transform: none !important;
  opacity: 1 !important;
}
.msg-sim-card > .msg-sim-loc-tag,
.msg-sim-card > .msg-sim-date,
.msg-sim-card > .msg-sim-loc-tag span,
.msg-sim-card > .msg-sim-date{
  font-family: "Noto Sans SC", sans-serif !important;
  font-size: 10px !important;
  font-weight: 300 !important;
  font-style: normal !important;
  letter-spacing: normal !important;
  text-transform: none !important;
  color: #3f3f3f !important;
  -webkit-text-fill-color: #3f3f3f !important;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.msg-sim-card > .msg-sim-texture::after,
.msg-sim-card > .msg-sim-loc-tag::after,
.msg-sim-card > .msg-sim-date::after{
  content: "";
  flex: 0 0 auto;
  width: 13px;
  height: 13px;
  background-position: center;
  background-repeat: no-repeat;
  background-size: contain;
  filter: brightness(0) invert(0.6);
}
.msg-sim-card > .msg-sim-texture{
  order: 1;
  border-bottom: 3px solid #ededed !important;
  border-top-left-radius: 8px !important;
  border-top-right-radius: 8px !important;
}
.msg-sim-card > .msg-sim-texture::before{
  content: "Text Image";
  font-family: "Noto Sans SC", sans-serif;
  font-size: 10px;
  font-weight: 300;
  color: #3f3f3f;
  -webkit-text-fill-color: #3f3f3f;
}
.msg-sim-card > .msg-sim-texture::after{
  background-image: url("https://atnefallhmhz.vercel.app/f/image-3j6a57.png");
}
.msg-sim-card > .msg-sim-loc-tag{ order: 2; }
.msg-sim-card > .msg-sim-loc-tag > div{ display: none !important; }
.msg-sim-card > .msg-sim-loc-tag::after{
  background-image: url("https://atnefallhmhz.vercel.app/f/location-f8utfy.png");
}
.msg-sim-card > .msg-sim-date{
  order: 3;
  border-bottom: none !important;
  border-bottom-left-radius: 8px !important;
  border-bottom-right-radius: 8px !important;
}
.msg-sim-card > .msg-sim-date::after{
  background-image: url("https://atnefallhmhz.vercel.app/f/time-5uqki3.png");
}
.msg-sim-card > div:nth-child(3){
  order: 4;
  position: relative !important;
  width: auto !important;
  max-width: 90% !important;
  align-self: flex-end;
  margin-top: 14px !important;
  padding: 13px 18px !important;
  background: #ffffff !important;
  border: 1px solid #E2E7EB !important;
  border-radius: 8px !important;
  box-shadow: none !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
}
.msg-sim-card > div:nth-child(3)::before{
  content: "";
  position: absolute;
  right: -8px;
  bottom: 6px;
  width: 0; height: 0;
  border-left: 8px solid #E2E7EB;
  border-top: 6px solid transparent;
  border-bottom: 6px solid transparent;
}
.msg-sim-card > div:nth-child(3)::after{
  content: "";
  position: absolute;
  right: -7px;
  bottom: 6px;
  width: 0; height: 0;
  border-left: 8px solid #ffffff;
  border-top: 6px solid transparent;
  border-bottom: 6px solid transparent;
}

.msg-them .msg-sim-card > div:nth-child(3){
  align-self: flex-start !important;
}
.msg-them .msg-sim-card > div:nth-child(3)::before{
  left: -8px; right: auto;
  border-left: 0;
  border-right: 8px solid #E2E7EB;
}
.msg-them .msg-sim-card > div:nth-child(3)::after{
  left: -7px; right: auto;
  border-left: 0;
  border-right: 8px solid #ffffff;
}
.msg-sim-card .msg-sim-text{
  font-family: "Noto Sans SC", sans-serif !important;
  font-size: 10.5px !important;
  font-weight: 320 !important;
  font-style: normal !important;
  line-height: 1.4 !important;
  color: #3f3f3f !important;
  -webkit-text-fill-color: #3f3f3f !important;
  width: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  position: relative;
  z-index: 1;

  display: flex !important;
  flex-direction: row !important;
  flex-wrap: nowrap !important;
  align-items: baseline !important;
  justify-content: center !important;
  overflow: hidden !important;
}

.msg-sim-card .msg-sim-text::before{ content: "ʚ"; flex: 0 0 auto; margin-right: 3px; }
.msg-sim-card .msg-sim-text::after { content: "ɞ"; flex: 0 0 auto; margin-left: 3px; }

.msg-sim-card .msg-sim-text span{
  display: block;
  flex: 0 1 auto;
  min-width: 0;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  margin: 0 !important;
  padding: 0 !important;
  font-family: "Noto Sans SC", sans-serif !important;
  font-style: normal !important;
}

.msg-sim-card .msg-sim-text span::before,
.msg-sim-card .msg-sim-text span::after{ content: none !important; }
.msg-sim-card .msg-sim-divider{ display: none !important; }

/* ========== 补丁：subtext chip ========== */

/* 1. toggle 图标换成和翻译一样的颜文字 ʚ✞ɞ */
.msg-subtext-toggle {
  width: auto !important;
  height: auto !important;
  min-width: 0 !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
  background: none !important;
  display: inline-flex !important;
  align-items: center !important;
  transform: none !important;
}
.msg-subtext-toggle svg { display: none !important; }
.msg-subtext-toggle::before {
  content: "ʚ✞ɞ" !important;
  color: #9a9aa5 !important;
  -webkit-text-fill-color: #9a9aa5 !important;
  font-size: 11px !important;
  line-height: 1 !important;
}

/* 2. 外层 chip：清背景/边框/阴影，不倾斜，放开宽度；上方留空 */
.msg-subtext-chip,
.msg-subtext-chip.is-me,
.msg-subtext-chip.is-open {
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  filter: none !important;
  transform: none !important;
  margin-top: 16px !important;
  max-width: 250px !important;
  position: relative !important;     /* 给展开态的透明点击层做定位基准 */
}

/* 展开后：隐藏 toggle 图标 + 不占位；toggle 变成覆盖气泡的透明点击层 → 点气泡收起 */
.msg-subtext-toggle.is-open {
  position: absolute !important;
  inset: 0 !important;
  width: auto !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  z-index: 5 !important;             /* 盖在气泡上方接收点击 */
  background: none !important;
  cursor: pointer !important;
}
.msg-subtext-toggle.is-open::before {
  content: "" !important;            /* 展开后不显示颜文字 */
}

/* 3. subtext 文字：去背景，边框保留，不倾斜，中灰字，放宽，蓝波点盖在文字上方 */
.msg-subtext-body {
  position: relative !important;
  box-sizing: border-box !important;
  background: none !important;
  border: 1px solid #ebe7eb !important;
  box-shadow: none !important;
  filter: none !important;
  transform: none !important;
  margin-top: 0px !important;
  padding: 3px 12px !important;
  min-width: 0px !important;
  max-width: none !important;
  font-size: 12px !important;
  color: #808080 !important;
  -webkit-text-fill-color: #808080 !important;
}
.msg-subtext-body::after {
  content: "" !important;
  position: absolute !important;
  inset: 0 !important;
  pointer-events: none !important;
  z-index: 2 !important;
  background:
    radial-gradient(circle, rgba(234, 235, 241, 0.7) 2.5px, transparent 2.6px) 0 0 / 16px 16px repeat,
    radial-gradient(circle, rgba(234, 235, 241, 0.7) 2.5px, transparent 2.6px) 8px 8px / 16px 16px repeat !important;
}

.typing {
  display: inline-flex;
  align-items: center;
  background-color: rgba(234, 235, 241, 0.7);
  border: 1px solid #ebe7eb !important;
  border-radius: 18px;
  padding: 8px 14px;
}

/* dot 换成图片 */
.typing .dot,
.typing::after {
  content: "";
  display: inline-block;
  width: 10px;               /* 按需调整 */
  height: 10px;              /* 按需调整 */
  background-image: url("https://atnefallhmhz.vercel.app/f/subtext-zh7bvc.png");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
}

.nuo-typing-bubble {
  background-color: rgba(234, 235, 241, 0.7) !important;
  border: 1px solid #ebe7eb !important;
  border-radius: 0 !important;
}
